import{az as e,P as l,Q as r,aQ as i}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const c=JSON.parse('{"title":"JWT与JWE的区别：Base64编码与加密的真相","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/服务端/jwe.md","filePath":"面试题/服务端/jwe.md","lastUpdated":1782478366000}'),p={name:"面试题/服务端/jwe.md"};function o(t,a,n,s,h,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="jwt与jwe的区别-base64编码与加密的真相" tabindex="-1">JWT与JWE的区别：Base64编码与加密的真相 <a class="header-anchor" href="#jwt与jwe的区别-base64编码与加密的真相" aria-label="Permalink to “JWT与JWE的区别：Base64编码与加密的真相”">​</a></h1><h2 id="核心结论先给你" tabindex="-1">核心结论先给你 <a class="header-anchor" href="#核心结论先给你" aria-label="Permalink to “核心结论先给你”">​</a></h2><ol><li><p><strong>Base64 不是加密，是「URL 安全的编码格式」</strong>，它的作用是把 JSON 结构转成可在 HTTP 头 / URL 里安全传输的字符串，和 “加密 / 保密” 没有关系；</p></li><li><p><strong>JWT 的核心设计目标是「防篡改」，不是「隐藏内容」</strong>，默认的签名版 JWT（JWS）从设计上就不需要加密载荷；</p></li><li><p><strong>全加密的 JWT 是存在的，且是官方标准</strong>，叫 <strong>JWE（JSON Web Encryption）</strong>，只是绝大多数业务场景用不上。</p></li></ol><p>下面逐层拆解清楚。</p><hr><h2 id="一、先澄清-为什么用-base64-和-明文-没关系" tabindex="-1">一、先澄清：为什么用 Base64？和 “明文” 没关系 <a class="header-anchor" href="#一、先澄清-为什么用-base64-和-明文-没关系" aria-label="Permalink to “一、先澄清：为什么用 Base64？和 “明文” 没关系”">​</a></h2><p>很多人会误以为 “Base64 是 JWT 选的加密方案”，这是完全的误解。</p><h3 id="_1-base64-的唯一作用-解决传输兼容性问题" tabindex="-1">1. Base64 的唯一作用：解决传输兼容性问题 <a class="header-anchor" href="#_1-base64-的唯一作用-解决传输兼容性问题" aria-label="Permalink to “1. Base64 的唯一作用：解决传输兼容性问题”">​</a></h3><p>Header 和 Payload 本质是 JSON 对象，但 HTTP 请求头、URL 参数里不能直接放带换行、空格、特殊符号的 JSON，也不能有中文等非 ASCII 字符。 Base64URL（JWT 用的是 URL 安全版 Base64）的作用只有一个：</p><blockquote><p>把结构化的 JSON 数据，转换成一串连续、URL 安全、无特殊字符的 ASCII 字符串，方便在网络中传递。</p></blockquote><p>它和 “加密、保密” 没有任何关系，就像把文件打包成 zip 是为了方便传输，不是为了加密上锁。</p><h3 id="_2-为什么不直接加密后传输" tabindex="-1">2. 为什么不直接加密后传输？ <a class="header-anchor" href="#_2-为什么不直接加密后传输" aria-label="Permalink to “2. 为什么不直接加密后传输？”">​</a></h3><p>这就回到了 JWT 的核心设计定位： <strong>JWT 要解决的核心问题是「防篡改」，不是「防偷看」。</strong></p><p>JWT 的设计前提是：</p><ul><li><p>传输层安全由 HTTPS 保证，正常生产环境下，令牌在网络传输中不会被中间人窃听；</p></li><li><p>Payload 里只放非敏感的身份标识（用户 ID、角色编码、过期时间），<strong>本来就不该放密码、手机号、身份证号等敏感信息</strong>；</p></li><li><p>令牌的核心诉求是「确保内容没被人改过」，而不是「不让人看到内容」。</p></li></ul><p>所以标准 JWT（准确叫 JWS，JSON Web Signature）的结构是： <code>编码后的Header . 编码后的Payload . 签名</code> 前两段只是编码方便传输，第三段签名才是安全核心 —— 保证前两段内容一旦被修改，服务端验签就会直接失败。</p><hr><h2 id="二、全加密方案当然可以-官方标准-jwe" tabindex="-1">二、全加密方案当然可以：官方标准 JWE <a class="header-anchor" href="#二、全加密方案当然可以-官方标准-jwe" aria-label="Permalink to “二、全加密方案当然可以：官方标准 JWE”">​</a></h2><p>你说的「把 header/payload 全部加密」，并不是什么新思路，JWT 官方规范里早就定义了，就是 <strong>JWE（JSON Web Encryption）</strong>。</p><h3 id="_1-jwe-是什么" tabindex="-1">1. JWE 是什么 <a class="header-anchor" href="#_1-jwe-是什么" aria-label="Permalink to “1. JWE 是什么”">​</a></h3><p>JWE 是 JWT 规范的一部分，它实现了<strong>载荷的对称 / 非对称加密</strong>，第三方拿到令牌也无法解密读取内容，只有持有解密密钥的服务端才能解析。</p><h3 id="_2-jwe-的结构-五段式-和-jws-三段式不同" tabindex="-1">2. JWE 的结构（五段式，和 JWS 三段式不同） <a class="header-anchor" href="#_2-jwe-的结构-五段式-和-jws-三段式不同" aria-label="Permalink to “2. JWE 的结构（五段式，和 JWS 三段式不同）”">​</a></h3><p>标准 JWE 格式：<code>Protected Header . Encrypted Key . IV . Ciphertext . Authentication Tag</code></p><ul><li><p>受保护头部：加密算法、密钥标识等元数据</p></li><li><p>加密密钥：用公钥 / 对称密钥加密后的内容密钥</p></li><li><p>初始化向量：加密算法的 IV 参数</p></li><li><p>密文：真正被加密后的 Payload 内容</p></li><li><p>认证标签：用于校验密文完整性，防止篡改</p></li></ul><p>最终外观上也是用点分隔的长字符串，但除了头部，其余部分全是密文，无法直接解码读取。</p><h3 id="_3-jwe-的适用场景" tabindex="-1">3. JWE 的适用场景 <a class="header-anchor" href="#_3-jwe-的适用场景" aria-label="Permalink to “3. JWE 的适用场景”">​</a></h3><p>只有对令牌内容保密性有强要求的场景才需要：</p><ul><li><p>令牌中必须携带少量敏感信息，且无法通过服务端查询获取；</p></li><li><p>传输环境无法保证 HTTPS（极少见的内网 / 特殊设备场景）；</p></li><li><p>高安全等级的业务（金融核心、政务涉密），需要多层安全防护。</p></li></ul><hr><h2 id="三、为什么-99-的业务都不用加密版-jwe" tabindex="-1">三、为什么 99% 的业务都不用加密版 JWE？ <a class="header-anchor" href="#三、为什么-99-的业务都不用加密版-jwe" aria-label="Permalink to “三、为什么 99% 的业务都不用加密版 JWE？”">​</a></h2><p>不是做不到，是<strong>投入产出比极低，甚至得不偿失</strong>。</p><h3 id="_1-性能开销差距巨大" tabindex="-1">1. 性能开销差距巨大 <a class="header-anchor" href="#_1-性能开销差距巨大" aria-label="Permalink to “1. 性能开销差距巨大”">​</a></h3><ul><li><p>JWS（普通签名版 JWT）：只做一次哈希签名校验，属于轻量计算，HS256 性能极高；</p></li><li><p>JWE（加密版）：需要完整的非对称加密 + 对称解密，计算开销是 JWS 的数倍甚至十几倍，高并发下会显著消耗服务端 CPU。</p></li></ul><h3 id="_2-失去了-自包含、易调试-的优势" tabindex="-1">2. 失去了 “自包含、易调试” 的优势 <a class="header-anchor" href="#_2-失去了-自包含、易调试-的优势" aria-label="Permalink to “2. 失去了 “自包含、易调试” 的优势”">​</a></h3><p>JWT 很大的便利在于：</p><ul><li><p>前端可以直接解码 Payload，读取过期时间，提前触发刷新逻辑；</p></li><li><p>开发、排查问题时，随手就能解码看令牌内容，定位问题快。 一旦加密，这些便利全部消失，前后端都无法直接读取，调试成本大幅上升。</p></li></ul><h3 id="_3-体积更大-进一步增加网络开销" tabindex="-1">3. 体积更大，进一步增加网络开销 <a class="header-anchor" href="#_3-体积更大-进一步增加网络开销" aria-label="Permalink to “3. 体积更大，进一步增加网络开销”">​</a></h3><p>本身 JWT 就比 sessionId 体积大，JWE 因为多了加密密钥、IV、认证标签等字段，体积会再膨胀 30%~50%，进一步加重请求头负担。</p><h3 id="_4-绝大多数场景下-加密是伪需求" tabindex="-1">4. 绝大多数场景下，加密是伪需求 <a class="header-anchor" href="#_4-绝大多数场景下-加密是伪需求" aria-label="Permalink to “4. 绝大多数场景下，加密是伪需求”">​</a></h3><ul><li><p>传输安全：HTTPS 已经保证了传输过程不会被窃听，加密 payload 属于重复防护；</p></li><li><p>内容安全：规范的做法是不在 payload 里放敏感信息，需要敏感数据走服务端查询，而不是靠加密令牌来藏数据。</p></li></ul><p>就像你不会把密码写在工牌上，再给工牌加个密码锁 —— 正确做法是工牌上只写姓名工号，敏感信息存在系统里。</p><hr><h2 id="四、常见认知误区澄清" tabindex="-1">四、常见认知误区澄清 <a class="header-anchor" href="#四、常见认知误区澄清" aria-label="Permalink to “四、常见认知误区澄清”">​</a></h2><h3 id="误区-1-jwt-明文就是不安全" tabindex="-1">误区 1：JWT 明文就是不安全 <a class="header-anchor" href="#误区-1-jwt-明文就是不安全" aria-label="Permalink to “误区 1：JWT 明文就是不安全”">​</a></h3><p>安全与否要看防护的是什么攻击：</p><ul><li><p>防篡改：JWS 有签名，非常安全，篡改即失效；</p></li><li><p>防传输窃听：靠 HTTPS，和 JWT 本身无关；</p></li><li><p>防内容泄露：JWS 确实不防，但规范做法是 payload 里不放敏感内容，不需要防。</p></li></ul><p>把敏感信息放进 payload 再加密，属于 “先制造问题再解决问题”，不如从源头就不放。</p><h3 id="误区-2-加密了就更安全" tabindex="-1">误区 2：加密了就更安全 <a class="header-anchor" href="#误区-2-加密了就更安全" aria-label="Permalink to “误区 2：加密了就更安全”">​</a></h3><p>如果密钥管理不当，加密版一样不安全；如果 payload 里全是非敏感信息，加密了也没有额外安全收益，反而增加了复杂度和故障风险。 安全的核心是<strong>最小权限 + 分层防护</strong>，不是盲目堆加密算法。</p><h3 id="误区-3-jwt-明文签名的-jws" tabindex="-1">误区 3：JWT = 明文签名的 JWS <a class="header-anchor" href="#误区-3-jwt-明文签名的-jws" aria-label="Permalink to “误区 3：JWT = 明文签名的 JWS”">​</a></h3><p>严格来说 JWT 是统称，包含 JWS（签名型，最常用）和 JWE（加密型）两种实现。 平时大家口头说的 “JWT”，默认都是指 JWS，因为它是绝对主流。</p><hr><h2 id="五、最佳实践总结" tabindex="-1">五、最佳实践总结 <a class="header-anchor" href="#五、最佳实践总结" aria-label="Permalink to “五、最佳实践总结”">​</a></h2><ol><li><p><strong>绝大多数业务场景</strong>：用标准 JWS（签名版 JWT）即可，Payload 只放用户 ID、角色、过期时间等非敏感字段，配合 HTTPS 传输，安全完全足够。</p></li><li><p><strong>确有保密需求</strong>：优先用官方标准 JWE，不要自己手写加密逻辑（极易出安全漏洞），优先选择非对称加密方案（公钥加密、私钥解密）。</p></li><li><p><strong>绝对不要做</strong>：把密码、身份证号、手机号等敏感信息放进 JWT Payload，哪怕是加密版也不推荐 —— 令牌的定位是身份凭证，不是数据存储载体。</p></li></ol><p>需要我补充一份 Node.js 环境下 JWE 加密解密的示例代码吗？</p><blockquote><p>（注：部分内容可能由 AI 生成）</p></blockquote>',56)])])}const b=e(p,[["render",o]]);export{c as __pageData,b as default};
